import clamp from '../../../utilities/clamp.js';
const LEAD_II_CODES = new Set(['5.6.3-9-2', '2:2']);
const GRID_MIN_LEADS = 8;
const GRID_MIN_SECONDS = 5;
const traceLayouts = new Map();
const warnedNames = new Set();
export function registerECGTraceLayout(name, layout, options = {}) {
    if (traceLayouts.has(name)) {
        throw new Error(`ECG trace layout "${name}" is already registered`);
    }
    traceLayouts.set(name, {
        factory: typeof layout === 'function' ? layout : () => layout,
        supports: options.supports,
    });
}
export function getECGTraceLayoutNames(context) {
    return Array.from(traceLayouts.entries())
        .filter(([, entry]) => !context || !entry.supports || entry.supports(context))
        .map(([name]) => name);
}
export function getECGTraceLayout(traceLayout, context) {
    if (typeof traceLayout !== 'string') {
        return traceLayout;
    }
    return traceLayouts.get(traceLayout)?.factory(context);
}
export function resolveDefaultECGTraceLayout(context) {
    const { channels, numberOfSamples = 0, samplingFrequency = 0 } = context;
    const isLong = !(numberOfSamples > 0 && samplingFrequency > 0) ||
        numberOfSamples / samplingFrequency >= GRID_MIN_SECONDS;
    return channels.length >= GRID_MIN_LEADS && isLong ? '3x4+1' : '12x1';
}
export function resolveECGTraceLayout(traceLayout, context) {
    const defaultLayout = resolveDefaultECGTraceLayout(context);
    const definition = getECGTraceLayout(traceLayout ?? defaultLayout, context);
    if (definition) {
        return definition;
    }
    if (!warnedNames.has(traceLayout)) {
        warnedNames.add(traceLayout);
        console.warn(`[ECG] Unknown trace layout "${traceLayout}", using "${defaultLayout}"`);
    }
    return getECGTraceLayout(defaultLayout, context);
}
export function hasViewTimeRegion(definition) {
    return definition.regions.some((region) => (region.time ?? 'view') === 'view');
}
export const ECG_LEAD_COPY_STRIDE = 1000;
const SINGLE_GROUP = { index: 0, count: 1 };
export function getECGLeadZ(channelIndex, copy, group = SINGLE_GROUP) {
    return (channelIndex + ECG_LEAD_COPY_STRIDE * (copy * group.count + group.index));
}
export function findECGLayoutForZ(layouts, z, group = SINGLE_GROUP) {
    const exact = layouts.find((item) => item.leadIndex === z);
    if (exact) {
        return exact;
    }
    const k = Math.floor(z / ECG_LEAD_COPY_STRIDE);
    if (k < 0 || k % group.count !== group.index) {
        return;
    }
    const baseZ = getECGLeadZ(z % ECG_LEAD_COPY_STRIDE, 0, group);
    return layouts.find((item) => item.leadIndex === baseZ);
}
export function resolveECGTraceCells(args) {
    const { definition, channels, numberOfSamples, viewSampleWindow, visibleChannels, group, } = args;
    const visible = visibleChannels ? new Set(visibleChannels) : undefined;
    const copies = new Map();
    const cells = [];
    definition.regions.forEach((region, regionIndex) => {
        const channelIndex = typeof region.lead === 'number'
            ? region.lead
            : findLeadByCode(channels, region.lead);
        const channel = channels[channelIndex];
        if (!channel) {
            return;
        }
        const copy = copies.get(channelIndex) ?? 0;
        copies.set(channelIndex, copy + 1);
        const leadIndex = getECGLeadZ(channelIndex, copy, group);
        const time = region.time ?? 'view';
        const [startSample, endSample] = time === 'view'
            ? viewSampleWindow
            : [
                Math.floor(clamp(time[0], 0, 1) * numberOfSamples),
                Math.floor(clamp(time[1], 0, 1) * numberOfSamples),
            ];
        cells.push({
            region,
            regionIndex,
            channel,
            channelIndex,
            leadIndex,
            visible: channel.data.length > 0 &&
                channel.visible !== false &&
                (!visible || visible.has(channelIndex)),
            startSample,
            endSample,
            label: region.label ?? channel.name,
        });
    });
    return cells;
}
function findLeadByCode(channels, lead) {
    const byCode = channels.findIndex((channel) => channel.code === lead);
    return byCode >= 0
        ? byCode
        : channels.findIndex((channel) => !channel.code && channel.name === lead);
}
function findLeadII(channels) {
    const byCode = channels.findIndex((channel) => LEAD_II_CODES.has(channel.code));
    if (byCode >= 0) {
        return byCode;
    }
    const byName = channels.findIndex((channel) => /\bii\b/.test((channel.name ?? '').toLowerCase()));
    if (byName >= 0) {
        return byName;
    }
    return channels.length > 1 ? 1 : 0;
}
function createRowsLayout({ channels, }) {
    const count = channels.length;
    return {
        regions: channels.map((_channel, index) => ({
            lead: index,
            bounds: {
                minX: 0,
                maxX: 1,
                minY: index / count,
                maxY: (index + 1) / count,
            },
            time: 'view',
        })),
    };
}
function createGridLayout(rowsPerColumn, nominalColumns, withRhythmStrip) {
    return ({ channels }) => {
        const columns = Math.max(nominalColumns, Math.ceil(channels.length / rowsPerColumn));
        const totalRows = rowsPerColumn + (withRhythmStrip ? 1 : 0);
        const regions = channels.map((_channel, index) => {
            const column = Math.floor(index / rowsPerColumn);
            const row = index % rowsPerColumn;
            return {
                lead: index,
                bounds: {
                    minX: column / columns,
                    maxX: (column + 1) / columns,
                    minY: row / totalRows,
                    maxY: (row + 1) / totalRows,
                },
                time: [column / columns, (column + 1) / columns],
            };
        });
        if (withRhythmStrip && channels.length) {
            regions.push({
                id: 'rhythm',
                lead: findLeadII(channels),
                bounds: { minX: 0, maxX: 1, minY: rowsPerColumn / totalRows, maxY: 1 },
                time: [0, 1],
            });
        }
        return { regions };
    };
}
const supportsGrid = ({ channels }) => channels.length >= GRID_MIN_LEADS;
registerECGTraceLayout('12x1', createRowsLayout);
registerECGTraceLayout('6x2', createGridLayout(6, 2, false), {
    supports: supportsGrid,
});
registerECGTraceLayout('3x4', createGridLayout(3, 4, false), {
    supports: supportsGrid,
});
registerECGTraceLayout('3x4+1', createGridLayout(3, 4, true), {
    supports: supportsGrid,
});
