import { loadECGWaveform } from './ecgWaveform.js';
import { getGenericViewportSourceDataId } from '../genericViewportDisplaySetAccess.js';
export class DefaultECGDataProvider {
    async load(dataId, options) {
        const sourceDataId = getGenericViewportSourceDataId(dataId);
        const { waveform } = await loadECGWaveform(sourceDataId, {
            multiplexGroupIndex: options?.multiplexGroupIndex,
        });
        return {
            id: dataId,
            type: 'ecg',
            ...waveform,
        };
    }
}
