import { utilities as metadataUtilities } from '@cornerstonejs/metadata';
import { MetadataModules } from '../../../enums/index.js';
import * as metaData from '../../../metaData.js';
export const ECG_DEFAULT_SWEEP_SPEED_MM_S = 25;
export const ECG_CLINICAL_SWEEP_SPEEDS = [12.5, 25, 50];
export const ECG_CLINICAL_SENSITIVITIES = [2.5, 5, 10, 20];
export const ECG_PX_PER_MM = 3.779;
export const ECG_SECONDS_WIDTH = 150;
export const ECG_CHANNEL_SPACING = 5;
export const ECG_DEFAULT_MV_PER_UNIT = metadataUtilities.ECG_DEFAULT_MV_PER_UNIT;
export const ECG_AMPLITUDE_INDEX_SIZE = metadataUtilities.ECG_AMPLITUDE_INDEX_SIZE;
export const ECG_RENDERING_COLORS = {
    gridMajor: '#7f0000',
    gridMinor: '#3f0000',
    baseline: '#7f4c00',
    trace: '#ffffff',
    label: '#ffff00',
    background: '#000000',
};
export function getECGChannelMvPerUnit(channel) {
    return Number.isFinite(channel.mvPerUnit) && channel.mvPerUnit > 0
        ? channel.mvPerUnit
        : ECG_DEFAULT_MV_PER_UNIT;
}
export function getECGFrameOfReferenceUID(imageId) {
    if (!imageId) {
        return;
    }
    return (metaData.get(MetadataModules.SOP_COMMON, imageId)?.sopInstanceUID ||
        `ecg:${imageId}`);
}
export async function loadECGWaveform(dataId, options = {}) {
    const ecgModule = metaData.getMetaData(MetadataModules.ECG, dataId, options);
    if (!ecgModule?.waveformData?.retrieveBulkData) {
        throw new Error(`[ECG] No ECG waveform data for ${dataId}`);
    }
    const { numberOfWaveformChannels: numberOfChannels, numberOfWaveformSamples: numberOfSamples, samplingFrequency, waveformBitsAllocated: bitsAllocated = 16, waveformSampleInterpretation: sampleInterpretation = 'SS', multiplexGroupLabel, multiplexGroupIndex = 0, totalMultiplexGroups: numberOfMultiplexGroups = 1, channelDefinitionSequence: channelDefinitions = [], } = ecgModule;
    const channelArrays = await ecgModule.waveformData.retrieveBulkData();
    const calibration = metaData.getMetaData(MetadataModules.CALIBRATION, dataId, options);
    const channels = [];
    for (let index = 0; index < numberOfChannels; index++) {
        const channelDefinition = channelDefinitions[index] || {};
        const source = channelDefinition.channelSourceSequence;
        const data = channelArrays[index] || new Int16Array(0);
        const { min, max } = computeECGMinMax(data);
        channels.push({
            name: source?.codeMeaning || `Channel ${index + 1}`,
            code: source?.codeValue,
            data,
            min,
            max,
            mvPerUnit: getECGChannelMvPerUnit(channelDefinition),
        });
    }
    return {
        waveform: {
            channels,
            numberOfChannels,
            numberOfSamples,
            samplingFrequency,
            bitsAllocated,
            sampleInterpretation,
            multiplexGroupLabel,
            multiplexGroupIndex,
            numberOfMultiplexGroups,
            calibration,
        },
        calibration,
    };
}
export function computeECGMinMax(data) {
    let min = 0;
    let max = 0;
    for (let index = 0; index < data.length; index++) {
        if (data[index] < min) {
            min = data[index];
        }
        if (data[index] > max) {
            max = data[index];
        }
    }
    return { min, max };
}
export function getDefaultECGValueRange(waveform) {
    let min = 0;
    let max = 0;
    waveform.channels.forEach((channel) => {
        min = Math.min(min, channel.min);
        max = Math.max(max, channel.max);
    });
    if (min === max) {
        return [-1, 1];
    }
    return [min, max];
}
