import { ECG_CHANNEL_SPACING, ECG_DEFAULT_SWEEP_SPEED_MM_S, ECG_PX_PER_MM, getECGChannelMvPerUnit, } from './ecgWaveform.js';
const AMPLITUDE_HEADROOM = 1.25;
export function getECGWorldWidth(args) {
    const { cells, numberOfSamples, samplingFrequency, pxPerSecond } = args;
    let recordPerWidth = 0;
    cells.forEach(({ visible, region, startSample, endSample }) => {
        const widthFraction = region.bounds.maxX - region.bounds.minX;
        if (visible && widthFraction > 0) {
            recordPerWidth = Math.max(recordPerWidth, (endSample - startSample) / numberOfSamples / widthFraction);
        }
    });
    const durationSeconds = numberOfSamples / samplingFrequency;
    return Math.max(1, Math.ceil(durationSeconds * (recordPerWidth || 1) * pxPerSecond));
}
export function computeECGTraceGeometry(args) {
    const { cells, ecgWidth, targetHeight, sensitivityMmMv } = args;
    const bands = getVisibleBands(cells);
    if (!bands.length) {
        return { channelScale: 1, ecgHeight: 1, layouts: [] };
    }
    const isCalibrated = sensitivityMmMv != null && sensitivityMmMv > 0;
    const totalExtent = bands.reduce((total, band) => total + (band.maxY - band.minY), 0);
    const fractions = bands.map((band) => totalExtent > 0 ? (band.maxY - band.minY) / totalExtent : 1 / bands.length);
    const range = (cell) => Math.max(1, cell.channel.max - cell.channel.min);
    const rangeMv = (cell) => range(cell) * getECGChannelMvPerUnit(cell.channel);
    let autoFitScale = 0;
    let ecgHeight;
    if (isCalibrated) {
        ecgHeight = Math.max(...bands.map((band, index) => (Math.max(...band.cells.map((cell) => range(cell) * scaleOf(cell) * AMPLITUDE_HEADROOM)) +
            ECG_CHANNEL_SPACING) /
            fractions[index]));
    }
    else {
        autoFitScale = Math.max(Number.EPSILON, Math.min(...bands.map((band, index) => (targetHeight * fractions[index] - ECG_CHANNEL_SPACING) /
            (Math.max(...band.cells.map(rangeMv)) * AMPLITUDE_HEADROOM))));
        ecgHeight = targetHeight;
    }
    function scaleOf(cell) {
        return isCalibrated
            ? sensitivityMmMv * ECG_PX_PER_MM * getECGChannelMvPerUnit(cell.channel)
            : autoFitScale * getECGChannelMvPerUnit(cell.channel);
    }
    const layouts = [];
    let top = 0;
    bands.forEach((band, index) => {
        const bandHeight = fractions[index] * ecgHeight;
        const yOffset = top + bandHeight;
        const itemHeight = bandHeight - ECG_CHANNEL_SPACING;
        const traceHeight = Math.max(...band.cells.map((cell) => range(cell) * scaleOf(cell) * AMPLITUDE_HEADROOM));
        const lowest = Math.min(0, ...band.cells.map((cell) => cell.channel.min * scaleOf(cell)));
        const baseline = yOffset - Math.max(0, itemHeight - traceHeight) / 2 + lowest;
        band.cells.forEach((cell) => {
            const { bounds } = cell.region;
            layouts.push({
                channel: cell.channel,
                label: cell.label,
                itemHeight,
                yOffset,
                baseline,
                channelScale: scaleOf(cell),
                xOffset: bounds.minX * ecgWidth,
                width: (bounds.maxX - bounds.minX) * ecgWidth,
                startSample: cell.startSample,
                endSample: cell.endSample,
                leadIndex: cell.leadIndex,
                regionIndex: cell.regionIndex,
            });
        });
        top = yOffset;
    });
    const firstVisible = bands[0].cells[0];
    return {
        channelScale: scaleOf(firstVisible),
        ecgHeight,
        layouts,
    };
}
function getVisibleBands(cells) {
    const bands = new Map();
    cells.forEach((cell) => {
        if (!cell.visible) {
            return;
        }
        const { minY, maxY } = cell.region.bounds;
        const key = `${minY.toFixed(6)}:${maxY.toFixed(6)}`;
        const band = bands.get(key) ?? { minY, maxY, cells: [] };
        band.cells.push(cell);
        bands.set(key, band);
    });
    return Array.from(bands.values()).sort((a, b) => a.minY - b.minY);
}
export function computeECGRenderMetrics(args) {
    const { canvas, cells, numberOfSamples, samplingFrequency, sweepSpeed, sensitivityMmMv, } = args;
    const resolvedSweepSpeed = sweepSpeed ?? ECG_DEFAULT_SWEEP_SPEED_MM_S;
    const pxPerSecond = resolvedSweepSpeed * ECG_PX_PER_MM;
    const ecgWidth = getECGWorldWidth({
        cells,
        numberOfSamples,
        samplingFrequency,
        pxPerSecond,
    });
    const canvasAspect = canvas.clientHeight && canvas.clientWidth
        ? canvas.clientHeight / canvas.clientWidth
        : 2 / 3;
    const { channelScale, ecgHeight, layouts } = computeECGTraceGeometry({
        cells,
        ecgWidth,
        targetHeight: ecgWidth * canvasAspect,
        sensitivityMmMv,
    });
    const clientWidth = canvas.clientWidth || canvas.width || ecgWidth;
    const clientHeight = canvas.clientHeight || canvas.height || ecgHeight;
    const worldToCanvasRatio = Math.min(clientWidth / Math.max(1, ecgWidth), clientHeight / Math.max(1, ecgHeight));
    return {
        metrics: {
            ecgWidth,
            ecgHeight,
            channelScale,
            worldToCanvasRatio,
            xOffsetCanvas: (clientWidth - ecgWidth * worldToCanvasRatio) / 2,
            yOffsetCanvas: (clientHeight - ecgHeight * worldToCanvasRatio) / 2,
            pxPerSecond,
            sweepSpeed: resolvedSweepSpeed,
        },
        layouts,
    };
}
