import Events from '../../enums/Events.js';
import eventTarget from '../../eventTarget.js';
import { resolveVolumeTexture } from './resolveVolumeTexture.js';
import { idleSampleDistanceMultiplierOf, sampleDistanceOf, } from './createVolumeMapper.js';
const claims = new WeakMap();
const heldActors = new Set();
export function claimLegacyActorTextureSet(actor, volume, name) {
    if (volume.claimTextureSet(name)) {
        claims.set(actor, { volume, name, held: true });
        heldActors.add(actor);
    }
}
export function holdLegacyActorTextureSet(actor, held) {
    const claim = claims.get(actor);
    if (!claim || claim.held === held) {
        return;
    }
    if (held) {
        claim.held = claim.volume.claimTextureSet(claim.name);
    }
    else {
        claim.volume.releaseTextureSet(claim.name);
        claim.held = false;
    }
    if (claim.held) {
        heldActors.add(actor);
    }
    else {
        heldActors.delete(actor);
    }
}
function rebindLegacyActor(actor) {
    const claim = claims.get(actor);
    const mapper = actor.getMapper();
    if (!mapper?.setScalarTexture) {
        return;
    }
    const { strategy, texture } = resolveVolumeTexture(claim.volume);
    if (!texture || strategy.name === claim.name) {
        return;
    }
    claim.volume.releaseTextureSet(claim.name);
    claim.name = strategy.name;
    claim.held = claim.volume.claimTextureSet(claim.name);
    if (!claim.held) {
        heldActors.delete(actor);
    }
    mapper.setScalarTexture(texture);
    mapper.setSampleDistance(sampleDistanceOf(mapper.getInputData(), texture, idleSampleDistanceMultiplierOf(mapper)));
    mapper.modified();
}
eventTarget.addEventListener(Events.VOLUME_TEXTURE_LIMITS_CHANGED, () => {
    [...heldActors].forEach(rebindLegacyActor);
});
