import { logging } from '@cornerstonejs/utils';
import { isUnsafeKey } from '../safeFunctions/schema.js';
const log = logging.metadataLog.getLogger('displayset', 'splitRuleSet');
function invalidEntry(id, message) {
    throw new Error(`Invalid split rule set entry "${id}": ${message}`);
}
function checkRuleId(id, seen) {
    if (typeof id !== 'string' || !id) {
        throw new Error(`A split rule needs a non-empty string id; got ${JSON.stringify(id)}`);
    }
    if (isUnsafeKey(id)) {
        invalidEntry(id, 'the id is not allowed; give the rule another id');
    }
    if (seen.has(id)) {
        invalidEntry(id, 'the id occurs more than once in the rule order');
    }
    seen.add(id);
    return id;
}
export function materializeSplitRules(registry, order) {
    if (!registry || typeof registry !== 'object' || Array.isArray(registry)) {
        throw new Error(`A split rule registry must be an object keyed by rule id: ${JSON.stringify(registry)}`);
    }
    if (!Array.isArray(order)) {
        throw new Error(`A split rule order must be an array of rule ids: ${JSON.stringify(order)}`);
    }
    const seen = new Set();
    const repeated = new Set();
    const result = [];
    for (const value of order) {
        if (typeof value === 'string' && seen.has(value)) {
            repeated.add(value);
            continue;
        }
        const id = checkRuleId(value, seen);
        if (!Object.prototype.hasOwnProperty.call(registry, id)) {
            invalidEntry(id, 'the rule order names an id that is not in the registry');
        }
        const entry = registry[id];
        if (!entry || typeof entry !== 'object') {
            invalidEntry(id, 'the entry must be an object');
        }
        if (entry.id !== undefined && entry.id !== id) {
            invalidEntry(id, `the entry states id "${entry.id}", but its key is the id. Remove the id, or make it equal to the key.`);
        }
        result.push({ ...entry, id });
    }
    if (repeated.size) {
        log.warn(`Split rule order: ${[...repeated].join(', ')} occurs more than once; the first place is used.`);
    }
    return result;
}
export function spliceById(list, splices) {
    if (!Array.isArray(list)) {
        throw new Error(`$spliceById: the target must be an array; got ${JSON.stringify(list)}`);
    }
    if (!Array.isArray(splices) || !splices.every(Array.isArray)) {
        throw new Error('$spliceById: the spec must be an array of [id, deleteCount, ...items] arrays');
    }
    const result = [...list];
    for (const [id, deleteCount, ...items] of splices) {
        if (typeof id !== 'string') {
            throw new Error(`$spliceById: the position must be an id string; got ${JSON.stringify(id)}. Use $splice for an index.`);
        }
        if (!Number.isInteger(deleteCount) || deleteCount < 0) {
            throw new Error(`$spliceById: the entry for "${id}" needs a deleteCount of 0 or more; got ${JSON.stringify(deleteCount)}`);
        }
        const start = result.findIndex((item) => item === id || item?.id === id);
        if (start === -1) {
            throw new Error(`$spliceById: no item has the id "${id}"`);
        }
        result.splice(start, deleteCount, ...items);
    }
    return result;
}
export function resolveSplitRuleSet(ruleSet) {
    if (!Array.isArray(ruleSet)) {
        throw new Error(`A split rule set must be an array of rules in evaluation order: ${JSON.stringify(ruleSet)}`);
    }
    const seen = new Set();
    for (const rule of ruleSet) {
        if (!rule || typeof rule !== 'object') {
            throw new Error(`A split rule must be an object: ${JSON.stringify(rule)}`);
        }
        checkRuleId(rule.id, seen);
    }
    return ruleSet;
}
